use serde_yaml_ng::Value;
use std::{
    fs,
    path::Path,
    process::{Command, Output},
};

fn write(root: &Path, path: &str, body: &str) {
    let file = root.join(path);
    fs::create_dir_all(file.parent().unwrap()).unwrap();
    fs::write(file, body).unwrap();
}
fn fixture(source: &Path, sidebar: &str) {
    write(
        source,
        "docusaurus.config.js",
        "module.exports = {title: 'Autogenerated'};",
    );
    write(
        source,
        "sidebars.js",
        &format!("module.exports = {{docs: {sidebar}}};"),
    );
}
fn convert(source: &Path, out: &Path, dry_run: bool) -> Output {
    let mut command = Command::new(env!("CARGO_BIN_EXE_zel"));
    command.arg("convert").arg(source).arg("--out").arg(out);
    if dry_run {
        command.arg("--dry-run");
    }
    command.output().unwrap()
}
fn success(output: Output) -> String {
    assert!(
        output.status.success(),
        "{}\n{}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    String::from_utf8(output.stdout).unwrap()
}
fn nav(out: &Path) -> Value {
    let value: Value =
        serde_yaml_ng::from_str(&fs::read_to_string(out.join("01-guide/_sidebar.yaml")).unwrap())
            .unwrap();
    value["nav"].clone()
}
fn names(nav: &Value) -> Vec<&str> {
    nav.as_sequence()
        .unwrap()
        .iter()
        .map(|item| item.as_str().or_else(|| item["label"].as_str()).unwrap())
        .collect()
}

#[test]
fn manual_document_links_include_linked_sources_once_and_preserve_labels() {
    let temp = tempfile::tempdir().unwrap();
    let source = temp.path().join("source");
    let out = temp.path().join("out");
    fixture(
        &source,
        "[{type:'category',label:'Manual',link:{type:'doc',id:'landing'},items:['child','landing']},{type:'category',label:'Only',link:{type:'doc',id:'landing'},items:[]},{type:'category',label:'Hidden',link:{type:'doc',id:'draft'},items:['child']}]",
    );
    write(
        &source,
        "docs/01-intro.md",
        "---\nid: landing\ntitle: Page title\nsidebar_label: Overview\n---\n# Heading",
    );
    write(&source, "docs/child.md", "# Child");
    write(&source, "docs/draft.md", "---\ndraft: true\n---\n# Draft");
    let report = success(convert(&source, &out, false));
    let nav = nav(&out);
    assert_eq!(names(&nav), ["Manual", "Only", "Hidden"]);
    assert_eq!(names(&nav[0]["items"]), ["Overview", "child"]);
    assert_eq!(nav[1]["page"], "01-intro");
    assert_eq!(names(&nav[2]["items"]), ["child"]);
    assert!(!out.join("01-guide/draft.mdx").exists());
    assert!(report.contains("marked draft or unlisted"));
    assert!(!report.contains("manual category"));
}

#[test]
fn generated_manual_indexes_preserve_text_and_link_to_nested_children() {
    let temp = tempfile::tempdir().unwrap();
    let source = temp.path().join("source");
    let out = temp.path().join("out");
    let sidebar = serde_json::json!([{
        "type":"category", "label":"Guides", "link": {
            "type":"generated-index", "title":"Read <Guide> {now}",
            "description":"Plain [text](javascript:bad) & <img/>\nexport default {}",
            "slug":"/old", "image":"/logo.png", "keywords":["docs"]
        }, "items":["welcome", {"type":"category", "label":"Nested", "link":{"type":"generated-index"}, "items":["deep/child"]}, {"type":"category", "label":"Group [literal]", "items":["last"]}]
    }]);
    fixture(&source, &sidebar.to_string());
    write(
        &source,
        "docs/welcome.md",
        "---\ntitle: Welcome [literal] {text}\n---\n# Welcome",
    );
    write(&source, "docs/deep/child.mdx", "# Child");
    write(&source, "docs/last.md", "# Last");
    let report = success(convert(&source, &out, false));
    let nav = nav(&out);
    assert_eq!(
        names(&nav[0]["items"]),
        ["Read <Guide> {now}", "welcome", "Nested", "Group [literal]"]
    );
    let raw = fs::read_to_string(out.join("01-guide/category/guides/index.mdx")).unwrap();
    let metadata: Value = serde_yaml_ng::from_str(raw.split("---").nth(1).unwrap()).unwrap();
    assert_eq!(metadata["title"], "Read <Guide> {now}");
    assert_eq!(metadata["route"], "/guide/old");
    assert!(raw.contains("[Welcome &#91;literal&#93; &#123;text&#125;](</guide/welcome>)"));
    assert!(raw.contains("[Nested](</guide/category/nested>)"));
    assert!(raw.contains("[Child](</guide/deep/child>)"));
    assert!(raw.contains("[Last](</guide/last>)"));
    assert!(raw.contains("&#60;img&#47;&#62;"));
    assert!(!raw.split("---").last().unwrap().contains("<img/>"));
    assert!(report.contains("category link fields not mapped: image, keywords"));
    assert!(!report.contains("reference "));
}

#[test]
fn generated_names_reserve_authored_and_excluded_routes_and_disambiguate_labels() {
    let temp = tempfile::tempdir().unwrap();
    let source = temp.path().join("source");
    let out = temp.path().join("out");
    fixture(
        &source,
        "[{type:'category',label:'Guides',link:{type:'generated-index'},items:['a']},{type:'category',label:'Guides',link:{type:'generated-index'},items:['b']},{type:'category',label:'../Café {x}',link:{type:'generated-index'},items:['a']}]",
    );
    for file in ["a.md", "b.md", "02-category/guides/index.md"] {
        write(&source, &format!("docs/{file}"), "# Authored");
    }
    write(
        &source,
        "docs/category/guides-2/index.md",
        "---\nunlisted: true\n---\n# Excluded",
    );
    success(convert(&source, &out, false));
    assert!(out.join("01-guide/category/guides-3/index.mdx").exists());
    assert!(out.join("01-guide/category/guides-4/index.mdx").exists());
    assert!(out.join("01-guide/category/cafe-x/index.mdx").exists());
    assert!(!out.join("01-guide/02-category/guides/index.mdx").exists());
    assert!(!out.join("01-guide/category/guides-2/index.mdx").exists());
    assert_eq!(
        fs::read_to_string(source.join("docs/02-category/guides/index.md")).unwrap(),
        "# Authored"
    );
}

#[test]
fn repeated_autogenerated_slices_share_one_generated_index_and_dry_run_writes_nothing() {
    let temp = tempfile::tempdir().unwrap();
    let source = temp.path().join("source");
    let out = temp.path().join("out");
    fixture(
        &source,
        "[{type:'autogenerated',dirName:'.'},{type:'autogenerated',dirName:'.'}]",
    );
    write(
        &source,
        "docs/01-Guides/_category_.yaml",
        "label: Guides\nlink:\n  type: generated-index\n  title: Begin here\n  description: Learn this system\n",
    );
    write(&source, "docs/01-Guides/one.md", "# One");
    write(
        &source,
        "docs/01-Guides/02-Nested/_category_.json",
        "{\"link\":{\"type\":\"generated-index\"}}",
    );
    write(&source, "docs/01-Guides/02-Nested/two.md", "# Two");
    let report = success(convert(&source, &out, true));
    assert!(report.contains("01-guide/category/guides/index.mdx"));
    assert!(!out.exists());
    success(convert(&source, &out, false));
    let nav = nav(&out);
    assert_eq!(nav[0], nav[1]);
    assert_eq!(
        fs::read_dir(out.join("01-guide/category")).unwrap().count(),
        2
    );
    let raw = fs::read_to_string(out.join("01-guide/category/guides/index.mdx")).unwrap();
    let metadata: Value = serde_yaml_ng::from_str(raw.split("---").nth(1).unwrap()).unwrap();
    assert_eq!(metadata["description"], "Learn this system");
    assert!(raw.contains("[One](</guide/guides/one>)"));
    assert!(raw.contains("[Two](</guide/guides/nested/two>)"));
}

#[test]
fn filtered_and_empty_categories_do_not_create_empty_indexes() {
    let temp = tempfile::tempdir().unwrap();
    let source = temp.path().join("source");
    let out = temp.path().join("out");
    fixture(
        &source,
        "[{type:'category',label:'Empty',link:{type:'generated-index'},items:[]},{type:'category',label:'Drafts',link:{type:'generated-index'},items:['draft']},{type:'category',label:'Foreign',link:{type:'generated-index'},items:[{type:'link',label:'Unsafe',href:'javascript:bad'}]}]",
    );
    write(&source, "docs/draft.md", "---\ndraft: true\n---\n# Hidden");
    let report = success(convert(&source, &out, false));
    assert!(report.contains("no eligible child documents"));
    assert!(!out.join("01-guide/category").exists());
    assert!(!out.join("01-guide/draft.mdx").exists());
}

#[test]
fn invalid_category_links_fail_before_output_and_leave_sources_untouched() {
    for link in [
        "[]",
        "{type:'other'}",
        "{type:'doc'}",
        "{type:'doc',id:'missing'}",
        "{type:'doc',id:7}",
        "{type:'generated-index',title:[]}",
        "{type:'generated-index',description:7}",
        "{type:'generated-index',title:'  '}",
    ] {
        let temp = tempfile::tempdir().unwrap();
        let source = temp.path().join("source");
        let out = temp.path().join("out");
        fixture(
            &source,
            &format!("[{{type:'category',label:'Bad',link:{link},items:['keep']}}]"),
        );
        write(&source, "docs/keep.md", "# Keep");
        assert!(!convert(&source, &out, false).status.success(), "{link}");
        assert!(!out.exists());
        assert_eq!(
            fs::read_to_string(source.join("docs/keep.md")).unwrap(),
            "# Keep"
        );
    }
}
